using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using Bimbridge.Engine.Coverage;
using Xunit;

namespace Bimbridge.Tests
{
    /// <summary>
    /// 0.9.1 Block B: the capability catalog cannot claim more than the code and the tests prove.
    /// Uses the offline API inventory (docs/0.9.1/inventory/revit-api-*.json, generated by tools/inventory/RevitApiInventory).
    /// </summary>
    public class CapabilityCatalogTests
    {
        private static readonly int[] Years = { 2022, 2023, 2024, 2025, 2026 };

        private static string Root()
        {
            var d = new DirectoryInfo(AppContext.BaseDirectory);
            while (d != null && !File.Exists(Path.Combine(d.FullName, "Bimbridge.sln"))) d = d.Parent;
            Assert.NotNull(d);
            return d.FullName;
        }

        private static JsonDocument Inventory(int year) =>
            JsonDocument.Parse(File.ReadAllText(Path.Combine(Root(), "docs", "0.9.1", "inventory", "revit-api-" + year + ".json")));

        private static HashSet<string> Commands(int year)
        {
            using var j = Inventory(year);
            return new HashSet<string>(j.RootElement.GetProperty("postable_command").EnumerateArray().Select(e => e.GetString()), StringComparer.Ordinal);
        }

        private static Dictionary<string, bool> Surfaces(int year)
        {
            using var j = Inventory(year);
            return j.RootElement.GetProperty("surfaces").EnumerateObject().ToDictionary(p => p.Name, p => p.Value.GetBoolean(), StringComparer.Ordinal);
        }

        [Fact]
        public void Ids_AreUnique_AndEveryDomainF01ToF37_HasAtLeastOneEntry()
        {
            var all = CapabilityCatalog.All;
            Assert.Equal(all.Count, all.Select(c => c.Id).Distinct(StringComparer.Ordinal).Count());
            Assert.All(all, c => Assert.Matches("^F(0[1-9]|[12][0-9]|3[0-7])-[A-Z0-9-]+-\\d{3}$", c.Id));
            Assert.All(all, c => Assert.StartsWith(c.Domain + "-", c.Id));
            for (var f = 1; f <= 37; f++) Assert.Contains(all, c => c.Domain == "F" + f.ToString("00"));
        }

        [Fact]
        public void NothingIsNativeVerified_WithoutANativeCampaign()
        {
            // There is no native 0.9.1 campaign yet: no capability may be declared NATIVE_VERIFIED.
            Assert.DoesNotContain(CapabilityCatalog.All, c => c.Status == CoverageStatus.NATIVE_VERIFIED);
        }

        [Fact]
        public void ImplementedClaims_PointToFilesThatExist_AndOfflineVerified_PointToTestsThatExist()
        {
            var root = Root();
            var asm = typeof(CapabilityCatalogTests).Assembly;
            foreach (var c in CapabilityCatalog.All)
            {
                var implemented = c.Status == CoverageStatus.IMPLEMENTED_UNVERIFIED || c.Status == CoverageStatus.OFFLINE_VERIFIED || c.Status == CoverageStatus.PARTIAL
                                  || c.Status == CoverageStatus.DYNAMIC_CSHARP_ONLY;
                if (implemented)
                {
                    Assert.True(c.Implementation.Length > 0, c.Id + ": no implementation file");
                    foreach (var f in c.Implementation) Assert.True(File.Exists(Path.Combine(root, f)), c.Id + ": does not exist " + f);
                }
                if (c.Status == CoverageStatus.OFFLINE_VERIFIED) Assert.True(c.Tests.Length > 0, c.Id + ": OFFLINE_VERIFIED without tests");
                foreach (var t in c.Tests)
                {
                    var cls = t.Split('.')[0];
                    var type = asm.GetType("Bimbridge.Tests." + cls);
                    Assert.True(type != null, c.Id + ": test does not exist " + t);
                    if (t.Contains('.')) Assert.True(type.GetMethod(t.Split('.')[1]) != null, c.Id + ": method does not exist " + t);
                }
            }
        }

        /// <summary>Symbol names ("Type" and "Type::Member", without signature) from a version's full listing.</summary>
        private static HashSet<string> SymbolNames(int year)
        {
            using var fs = File.OpenRead(Path.Combine(Root(), "docs", "0.9.1", "inventory", "revit-symbols-" + year + ".txt.gz"));
            using var gz = new System.IO.Compression.GZipStream(fs, System.IO.Compression.CompressionMode.Decompress);
            using var r = new StreamReader(gz);
            var set = new HashSet<string>(StringComparer.Ordinal);
            string line;
            while ((line = r.ReadLine()) != null)
            {
                var s = line.Split('|')[2];
                var p = s.IndexOf('('); if (p > 0) s = s.Substring(0, p);
                var b = s.IndexOf('['); if (b > 0) s = s.Substring(0, b);
                set.Add(s.Replace('+', '.'));
            }
            return set;
        }

        /// <summary>Does the surface exist in that version? Curated surface list or, if it is not there, the full symbol listing.</summary>
        private static bool Exists(Dictionary<int, Dictionary<string, bool>> surfaces, Dictionary<int, HashSet<string>> symbols, int y, string s) =>
            surfaces[y].TryGetValue(s, out var v) ? v : symbols[y].Contains(s);

        [Fact]
        public void ApiClaims_MatchTheOfflineInventory()
        {
            var surfaces = Years.ToDictionary(y => y, Surfaces);
            var symbols = Years.ToDictionary(y => y, SymbolNames);
            foreach (var c in CapabilityCatalog.All)
            {
                foreach (var s in c.ApiSurfaces)
                    Assert.True(surfaces[2026].ContainsKey(s) || Years.Any(y => symbols[y].Contains(s)) || c.Status == CoverageStatus.UNSUPPORTED_BY_PUBLIC_API,
                        c.Id + ": surface " + s + " is not in the inventory (neither curated nor full listing)");
                if (c.Status == CoverageStatus.DYNAMIC_CSHARP_ONLY && c.ApiSurfaces.Length > 0)
                    Assert.True(c.ApiSurfaces.Any(s => Years.Any(y => Exists(surfaces, symbols, y, s))), c.Id + ": DYNAMIC_CSHARP_ONLY without public API in any version");
                // "No public API" is proven: the cited surface does not exist in ANY version 2022–2026.
                if (c.Status == CoverageStatus.UNSUPPORTED_BY_PUBLIC_API)
                    Assert.All(c.ApiSurfaces, s => Assert.True(Years.All(y => !Exists(surfaces, symbols, y, s)), c.Id + ": " + s + " does exist in some version"));
            }
        }

        [Fact]
        public void PostableCommandsCited_ExistInAtLeastOneVersion_NoInventedNames()
        {
            var union = new HashSet<string>(Years.SelectMany(Commands), StringComparer.Ordinal);
            var invented = CapabilityCatalog.All.SelectMany(c => c.PostableCommands.Select(p => c.Id + ":" + p)).Where(x => !union.Contains(x.Split(':')[1])).ToList();
            Assert.True(invented.Count == 0, "commands that do not exist in PostableCommand: " + string.Join(", ", invented));
        }

        [Fact]
        public void EveryPostableCommand_OfEveryVersion_IsClassifiedIntoADomain()
        {
            foreach (var y in Years)
            {
                var cmds = Commands(y);
                Assert.True(cmds.Count > 500, y + ": incomplete inventory (" + cmds.Count + ")");
                foreach (var cmd in cmds)
                {
                    var d = CommandClassifier.Classify(cmd, out _);
                    Assert.Matches("^F(0[1-9]|[12][0-9]|3[0-7])$", d);
                }
            }
        }

        [Fact]
        public void TypedStrategies_ReferenceOperationsThatExistInTheOpCatalog()
        {
            // A "typed:<op>" capability may only cite a write operation that really exists (OpCatalog).
            var kinds = new HashSet<string>(Bimbridge.Engine.OpCatalog.All.Select(o => o.Kind), StringComparer.Ordinal);
            foreach (var c in CapabilityCatalog.All.Where(c => c.Strategy != null && c.Strategy.StartsWith("typed:", StringComparison.Ordinal)))
                Assert.True(kinds.Contains(c.Strategy.Substring(6)), c.Id + ": operation " + c.Strategy + " does not exist in OpCatalog");
        }

        [Fact]
        public void Summary_CountsMatchTheCatalog()
        {
            var s = CapabilityCatalog.Summary();
            Assert.Equal((long)CapabilityCatalog.All.Count, s["capabilities"]);
            var byStatus = (Dictionary<string, object>)s["by_status"];
            Assert.Equal((long)CapabilityCatalog.All.Count, byStatus.Values.Sum(v => (long)v));
        }
    }
}
